// API @jinx-ui/react воспроизведён по типовым соглашениям (useToast/Input/Button) — сверьте имена пропсов с версией пакета в проекте.
import { useState, type FormEvent } from 'react';
import { Button, Card, Input, Stack, Text, useToast } from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const [email, setEmail] = useState('');
  const toast = useToast();

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    toast.show({
      title: 'Готово',
      description: `Письмо отправлено на ${email}`,
      variant: 'success',
      placement: 'bottom-right',
    });

    setEmail('');
  };

  return (
    <Card className="jx-card">
      <form onSubmit={handleSubmit} noValidate={false}>
        <Stack direction="column" style={{ gap: 'var(--jx-space-4)' }}>
          <Text as="h2" variant="heading-sm">
            Подписка на рассылку
          </Text>

          <Input
            id="newsletter-email"
            name="email"
            type="email"
            label="Почта"
            placeholder="you@example.com"
            autoComplete="email"
            required
            value={email}
            onChange={(event) => setEmail(event.target.value)}
          />

          <Button type="submit" variant="primary" disabled={email.trim().length === 0}>
            Подписаться
          </Button>
        </Stack>
      </form>
    </Card>
  );
}

